-- One-time import: remaining Aichi-Nagoya 2026 sports players (94 athletes across
-- 19 sports, excluding Athletics which was imported separately). Photos already
-- uploaded to S3. Resolves the edition by name pattern rather than a hardcoded id,
-- since local dev and production edition ids/slugs have diverged.
BEGIN;

-- Media library catalog rows.

DO $$
DECLARE target_id INT;
BEGIN
  SELECT id INTO target_id FROM game_editions WHERE name LIKE '%Aichi-Nagoya%2026%';
  IF target_id IS NULL THEN RAISE EXCEPTION 'Could not find the Aichi-Nagoya 2026 edition — check game_editions.name manually'; END IF;
END $$;
COMMIT;
